/** Хвост номера: последние четыре цифры без разделителей. */
function tail(phone: string): string {
  return phone.replace(/\D/gu, '').slice(-4);
}

/** Маскирование телефона в логах: хвост из четырёх цифр, остальное звёздочками. */
export function maskPhone(phone: string): string {
  const digits = tail(phone);
  return digits === '' ? '***' : `***${digits}`;
}
